<div class="portal-shell"><?php require __DIR__.'/../includes/sidebar.php';?><main class="portal-main"><header class="portal-page-header"><div><span class="eyebrow">FINANCE</span><h1 class="mt-2 mb-1"><?=$id?'Edit expense':'Record expense'?></h1><p class="text-muted mb-0">Keep operating costs traceable and report-ready.</p></div><a class="btn btn-outline-secondary" href="<?=url('admin/expenses.php')?>">Back</a></header><?php if($errors):?><div class="alert alert-danger"><ul class="mb-0"><?php foreach($errors as $e):?><li><?=e($e)?></li><?php endforeach;?></ul></div><?php endif;?><section class="portal-card form-card-narrow"><form method="post"><?=csrf_field()?><div class="row g-3"><div class="col-md-6"><label class="form-label">Category</label><select class="form-select" name="category" required><option value="">Choose category</option><?php foreach($categories as $c):?><option value="<?=e($c)?>" <?=$value('category')===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Amount</label><div class="input-group"><span class="input-group-text">₱</span><input class="form-control" type="number" min="0.01" step="0.01" name="amount" required value="<?=e($value('amount'))?>"></div></div><div class="col-md-6"><label class="form-label">Expense date</label><input class="form-control" type="date" name="expense_date" required value="<?=e($value('expense_date',date('Y-m-d')))?>"></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" name="description" maxlength="500" rows="4" required><?=e($value('description'))?></textarea></div><div class="col-12"><button class="btn btn-coffee" type="submit"><?=$id?'Save changes':'Record expense'?></button></div></div></form></section></main></div><?php require __DIR__.'/../includes/footer.php';?>
